(h) => {
    h.innerHTML = `<div class="row"><label>顶点 A,B,C <input type="text" id="ex05_pts" value="200,60 80,220 320,200" style="width: 200px; padding: 4px;"></label><button class="primary" id="ex05_run">算</button></div><div id="ex05_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('ex05_run').onclick = () => {
      const pts = document.getElementById('ex05_pts').value.split(/\s+/).map(s => s.split(',').map(Number));
      if (pts.length !== 3 || pts.some(p => p.length !== 2 || isNaN(p[0]))) {
        document.getElementById('ex05_out').innerHTML = '请输入 3 个 (x,y) 坐标';
        return;
      }
      const A = pts[0], B = pts[1], C = pts[2];
      const G = [(A[0]+B[0]+C[0])/3, (A[1]+B[1]+C[1])/3];
      const a1 = B[1]-C[1], b1 = -(B[0]-C[0]), c1 = a1*A[0] + b1*A[1];
      const a2 = A[1]-C[1], b2 = -(A[0]-C[0]), c2 = a2*B[0] + b2*B[1];
      const det = a1*b2 - a2*b1;
      if (Math.abs(det) < 1) { document.getElementById('ex05_out').innerHTML = '三点共线！'; return; }
      const H = [(c1*b2 - c2*b1)/det, (a1*c2 - a2*c1)/det];
      const mABx = (A[0]+B[0])/2, mABy = (A[1]+B[1])/2;
      const mACx = (A[0]+C[0])/2, mACy = (A[1]+C[1])/2;
      const p1 = B[1]-A[1], q1 = -(B[0]-A[0]), r1 = p1*mABx + q1*mABy;
      const p2 = C[1]-A[1], q2 = -(C[0]-A[0]), r2 = p2*mACx + q2*mACy;
      const det2 = p1*q2 - p2*q1;
      const O = [(r1*q2 - r2*q1)/det2, (p1*r2 - p2*r1)/det2];
      const cross = (H[0]-G[0])*(O[1]-G[1]) - (H[1]-G[1])*(O[0]-G[0]);
      const collinear = Math.abs(cross) < 0.5;
      document.getElementById('ex05_out').innerHTML = `G = (${G[0].toFixed(1)}, ${G[1].toFixed(1)})<br>H = (${H[0].toFixed(1)}, ${H[1].toFixed(1)})<br>O = (${O[0].toFixed(1)}, ${O[1].toFixed(1)})<br>三心<strong style="color:${collinear?'#10b981':'#ef4444'};">${collinear?'共线 ✓':'不共线？'}</strong>`;
    };
  }

(h) => {
