(h) => {
    h.innerHTML = `<div class="row"><label>w <input type="number" id="ex07_w" value="1" step="0.1" style="width: 60px;"></label><label>x <input type="number" id="ex07_x" value="0" step="0.1" style="width: 60px;"></label><label>y <input type="number" id="ex07_y" value="0" step="0.1" style="width: 60px;"></label><label>z <input type="number" id="ex07_z" value="0" step="0.1" style="width: 60px;"></label><button class="primary" id="ex07_norm">归一化</button><button class="ghost" id="ex07_rotate">旋转 90° (Z)</button></div><canvas id="ex07_cv" width="400" height="400" style="margin-top:12px; max-width:100%; border:1px solid var(--line); border-radius: 6px;"></canvas>`;
    const cv = document.getElementById('ex07_cv');
    const ctx = cv.getContext('2d');
    const W = 400, H = 400;
    const drawQuat = (w, x, y, z) => {
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      // 3D 投影
      const cx = W / 2, cy = H / 2;
      const scale = 80;
      // 画 3 个轴
      ctx.strokeStyle = '#d1d5db'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(cx - 100, cy); ctx.lineTo(cx + 100, cy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx, cy + 100); ctx.stroke();
      // 把四元数看作"旋转"：绕 (x, y, z) 方向 2*acos(w) 角度
      const norm = Math.sqrt(w * w + x * x + y * y + z * z);
      if (norm < 1e-6) return;
      const wN = w / norm, xN = x / norm, yN = y / norm, zN = z / norm;
      const angle = 2 * Math.acos(Math.min(1, Math.max(-1, wN)));
      const sinHalf = Math.sqrt(1 - wN * wN);
      let ux, uy, uz;
      if (sinHalf < 1e-6) { ux = 1; uy = 0; uz = 0; }
      else { ux = xN / sinHalf; uy = yN / sinHalf; uz = zN / sinHalf; }
      // 显示角度与轴
      ctx.fillStyle = '#1f2937'; ctx.font = 'bold 14px sans-serif';
      ctx.fillText(`旋转: ${(angle * 180 / Math.PI).toFixed(1)}°`, 10, 20);
      ctx.fillText(`轴: (${ux.toFixed(2)}, ${uy.toFixed(2)}, ${uz.toFixed(2)})`, 10, 40);
      // 画轴线
      ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 2;
      const ax1 = cx - ux * 100, ay1 = cy + uy * 100;
      const ax2 = cx + ux * 100, ay2 = cy - uy * 100;
      ctx.beginPath(); ctx.moveTo(ax1, ay1); ctx.lineTo(ax2, ay2); ctx.stroke();
      // 画从原点到 (1,0,0) 旋转后的点
      const p = [1, 0, 0];
      // Rodrigues
      const cos = Math.cos(angle), sin = Math.sin(angle);
      const dot = ux * p[0] + uy * p[1] + uz * p[2];
      const crossX = uy * p[2] - uz * p[1];
      const crossY = uz * p[0] - ux * p[2];
      const crossZ = ux * p[1] - uy * p[0];
      const px = p[0] * cos + crossX * sin + ux * dot * (1 - cos);
      const py = p[1] * cos + crossY * sin + uy * dot * (1 - cos);
      const pz = p[2] * cos + crossZ * sin + uz * dot * (1 - cos);
      // 画原始点（灰）和旋转点（红）
      ctx.fillStyle = '#9ca3af'; ctx.beginPath(); ctx.arc(cx + p[0] * 100, cy - p[1] * 100, 5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#ef4444';
      ctx.beginPath(); ctx.arc(cx + px * 100, cy - py * 100, 6, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#1f2937'; ctx.font = '11px sans-serif';
      ctx.fillText(`P' = (${px.toFixed(2)}, ${py.toFixed(2)}, ${pz.toFixed(2)})`, 10, H - 10);
    };
    document.getElementById('ex07_norm').onclick = () => {
      let w = +document.getElementById('ex07_w').value;
      let x = +document.getElementById('ex07_x').value;
      let y = +document.getElementById('ex07_y').value;
      let z = +document.getElementById('ex07_z').value;
      const n = Math.sqrt(w*w+x*x+y*y+z*z);
      if (n > 1e-6) { w /= n; x /= n; y /= n; z /= n; }
      document.getElementById('ex07_w').value = w.toFixed(3);
      document.getElementById('ex07_x').value = x.toFixed(3);
      document.getElementById('ex07_y').value = y.toFixed(3);
      document.getElementById('ex07_z').value = z.toFixed(3);
      drawQuat(w, x, y, z);
    };
    document.getElementById('ex07_rotate').onclick = () => {
      // 绕 Z 轴 90°: cos(45°), 0, 0, sin(45°)
      const s = Math.sqrt(2) / 2;
      document.getElementById('ex07_w').value = s.toFixed(3);
      document.getElementById('ex07_x').value = 0;
      document.getElementById('ex07_y').value = 0;
      document.getElementById('ex07_z').value = s.toFixed(3);
      drawQuat(s, 0, 0, s);
    };
    drawQuat(1, 0, 0, 0);
  }

(h) => {
    h.innerHTML = `<div class="row"><label>a <input type="number" id="ex08_a" value="-1" step="0.5" style="width: 80px;"></label><label>b <input type="number" id="ex08_b" value="1" step="0.5" style="width: 80px;"></label><button class="primary" id="ex08_plot">画曲线</button><button class="ghost" id="ex08_btc">比特币曲线</button></div><canvas id="ex08_cv" width="400" height="300" style="margin-top:12px; max-width:100%; border:1px solid var(--line); border-radius: 6px;"></canvas><div id="ex08_info" style="margin-top: 8px; padding: 10px; background: #faf5ff; border-radius: 6px; font-size: 13px;"></div>`;
    const cv = document.getElementById('ex08_cv');
    const ctx = cv.getContext('2d');
    const W = 400, H = 300;
    const draw = (a, b) => {
      cv.width = W; cv.height = H;
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      ctx.strokeStyle = '#f3f4f6'; ctx.lineWidth = 1;
      for (let i = 0; i <= 16; i++) {
        ctx.beginPath(); ctx.moveTo(i * W / 16, 0); ctx.lineTo(i * W / 16, H); ctx.stroke();
