      ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();
      const xMin = -4, xMax = 4, yMax = 4;
      ctx.fillStyle = '#7c3aed';
      for (let px = 0; px < W; px++) {
