(h) => {
    h.innerHTML = `<div class="row"><label>Px <input type="number" id="ex09_px" value="0" step="0.1" style="width: 70px;"></label><label>Py <input type="number" id="ex09_py" value="0" step="0.1" style="width: 70px;"></label><label>Qx <input type="number" id="ex09_qx" value="0.5" step="0.1" style="width: 70px;"></label><label>Qy <input type="number" id="ex09_qy" value="0" step="0.1" style="width: 70px;"></label><button class="primary" id="ex09_run">▶ 算双曲距离</button></div><canvas id="ex09_cv" width="400" height="400" style="margin-top:12px; max-width:100%; border:1px solid var(--line); border-radius: 6px;"></canvas><div id="ex09_info" style="margin-top: 8px; padding: 10px; background: #faf5ff; border-radius: 6px; font-size: 13px;"></div>`;
    const cv = document.getElementById('ex09_cv');
    const ctx = cv.getContext('2d');
    const W = 400, H = 400;
    const draw = (px, py, qx, qy) => {
      cv.width = W; cv.height = H;
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      // 单位圆（边界 = 无穷远）
      const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 10;
      // 双曲面：内点染色，越靠边界越深
      const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, R);
      grad.addColorStop(0, '#f0f9ff');
      grad.addColorStop(0.5, '#dbeafe');
      grad.addColorStop(0.95, '#bfdbfe');
      grad.addColorStop(1, '#7c3aed');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
      // 边界
      ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
      // 把 P, Q 画在圆内
      const drawP = (x, y, color, label) => {
        const pxp = cx + x * R, pyp = cy - y * R;
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(pxp, pyp, 6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(pxp, pyp, 3, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#1f2937'; ctx.font = 'bold 12px sans-serif';
        ctx.fillText(label, pxp + 8, pyp - 8);
      };
      drawP(px, py, '#ef4444', 'P');
      drawP(qx, qy, '#10b981', 'Q');
      // 测地线（圆弧）
      ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2;
      ctx.beginPath();
      // 简化：从 P 到 Q 画一条直线（在庞加莱里这不是真的测地线，但示意）
      const ppx = cx + px * R, ppy = cy - py * R;
      const qpx = cx + qx * R, qpy = cy - qy * R;
      ctx.moveTo(ppx, ppy); ctx.lineTo(qpx, qpy);
      ctx.stroke();
      // 计算双曲距离
      const p2 = px * px + py * py, q2 = qx * qx + qy * qy;
      let info = '';
      if (p2 < 1 && q2 < 1) {
        const eDist = Math.sqrt((px - qx) ** 2 + (py - qy) ** 2);
        const arg = 1 + 2 * eDist * eDist / ((1 - p2) * (1 - q2));
        const hDist = Math.acosh(arg);
        info = `欧氏距离 = ${eDist.toFixed(3)}<br>双曲距离 = <strong style="color:#7c3aed;">${hDist.toFixed(3)}</strong>`;
      } else {
        info = '<strong style="color:#ef4444;">点必须在单位圆内</strong>';
      }
      document.getElementById('ex09_info').innerHTML = info;
    };
    document.getElementById('ex09_run').onclick = () => {
      draw(+document.getElementById('ex09_px').value, +document.getElementById('ex09_py').value,
           +document.getElementById('ex09_qx').value, +document.getElementById('ex09_qy').value);
    };
    draw(0, 0, 0.5, 0);
  }

