        ctx.beginPath(); ctx.moveTo(0, i * H / 16); ctx.lineTo(W, i * H / 16); ctx.stroke();
      }
      // 坐标轴
      ctx.strokeStyle = '#374151'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(0, H / 2); ctx.lineTo(W, H / 2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();
      // 单位圆
      ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 1.5; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.arc(W / 2, H / 2, 50, 0, Math.PI * 2); ctx.stroke();
      ctx.setLineDash([]);
      if (sweep) {
        // 撒点：圆内所有点 → 1/z
        for (let i = 0; i < 300; i++) {
          const x = (Math.random() - 0.5) * 2;
          const y = (Math.random() - 0.5) * 2;
          const m2 = x * x + y * y;
          if (m2 < 0.01) continue;
          // f(z) = (a(x+yi) + b) / (c(x+yi) + d) = (X + Yi) / (U + Vi)
          const X = a * x + b;
          const Y = a * y;
          const U = c * x + d;
          const V = c * y;
          const den = U * U + V * V;
          if (den < 1e-6) continue;
          const fx = (X * U + Y * V) / den;
          const fy = (Y * U - X * V) / den;
          // 画原 z
          const px = W / 2 + x * 50;
          const py = H / 2 - y * 50;
          ctx.fillStyle = '#3b82f6'; ctx.globalAlpha = 0.4;
          ctx.beginPath(); ctx.arc(px, py, 1, 0, Math.PI * 2); ctx.fill();
          // 画 f(z)
          const fpx = W / 2 + fx * 50;
          const fpy = H / 2 - fy * 50;
          ctx.fillStyle = '#ef4444';
          ctx.beginPath(); ctx.arc(fpx, fpy, 1, 0, Math.PI * 2); ctx.fill();
        }
        ctx.globalAlpha = 1;
      } else {
        // 单点
        const X = a * zr + b;
        const Y = a * zi;
        const U = c * zr + d;
        const V = c * zi;
        const den = U * U + V * V;
        if (den < 1e-6) {
          document.getElementById('ex10_info').innerHTML = `<strong style="color:#ef4444;">分母 = 0, f(z) → ∞</strong>`;
          return;
        }
        const fx = (X * U + Y * V) / den;
        const fy = (Y * U - X * V) / den;
        // 画原 z
        const px = W / 2 + zr * 50;
        const py = H / 2 - zi * 50;
        ctx.fillStyle = '#3b82f6';
        ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#1f2937'; ctx.font = '11px sans-serif';
        ctx.fillText(`z = ${zr}+${zi}i`, px + 8, py + 4);
        // 画 f(z)
        const fpx = W / 2 + fx * 50;
        const fpy = H / 2 - fy * 50;
        ctx.fillStyle = '#ef4444';
        ctx.beginPath(); ctx.arc(fpx, fpy, 6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(fpx, fpy, 3, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#1f2937';
        ctx.fillText(`f(z) = ${fx.toFixed(2)}+${fy.toFixed(2)}i`, fpx + 8, fpy - 8);
        // 连线
        ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(fpx, fpy); ctx.stroke();
        ctx.setLineDash([]);
        document.getElementById('ex10_info').innerHTML = `a=${a} b=${b} c=${c} d=${d} z=${zr}+${zi}i<br>f(z) = (${X}+${Y}i) / (${U}+${V}i) = <strong style="color:#7c3aed;">${fx.toFixed(3)} + ${fy.toFixed(3)}i</strong>`;
      }
    };
    document.getElementById('ex10_run').onclick = () => {
      draw(+document.getElementById('ex10_a').value, +document.getElementById('ex10_b').value,
           +document.getElementById('ex10_c').value, +document.getElementById('ex10_d').value,
