(h) => {
    h.innerHTML = `<div class="row"><label>a <input type="number" id="ex12_a" value="2" min="-30" max="30"></label><label>b <input type="number" id="ex12_b" value="1" min="-30" max="30"></label><button class="primary" id="ex12_run">验证</button><button class="ghost" id="ex12_scan">扫 1-30</button></div><div id="ex12_out" style="margin-top: 12px; padding: 12px; background: #f0f9ff; border-radius: 8px; font-family: 'Courier New', monospace;"></div><canvas id="ex12_cv" width="360" height="360" style="margin-top: 12px; max-width: 100%; border: 1px solid var(--line); border-radius: 6px;"></canvas>`;
    const factorize = n => { const f = []; for (let p = 2; p * p <= n; p++) while (n % p === 0) { f.push(p); n /= p; } if (n > 1) f.push(n); return f; };
    const isPrime = n => n < 2 ? false : (n === 2 ? true : factorize(n).length === 1);
    const isGaussianPrime = (a, b) => {
      if (a === 0 && b === 0) return false;
      const N = a * a + b * b;
      if (a === 0 || b === 0) return isPrime(Math.abs(a === 0 ? b : a));
      return isPrime(N) && (N % 4 === 3 || (N % 4 === 1 && Math.abs(a) === 1) || (N === 5 && (a === 2 || a === -2)));
    };
    document.getElementById('ex12_run').onclick = () => {
      const a = +document.getElementById('ex12_a').value;
      const b = +document.getElementById('ex12_b').value;
      const N = a * a + b * b;
      const gp = isGaussianPrime(a, b);
      document.getElementById('ex12_out').innerHTML = `${a}+${b}i<br>范数 N = ${a}²+${b}² = <strong style="color:#7c3aed;">${N}</strong><br>${gp ? '<strong style="color:#10b981;">✓ 是高斯素数</strong>' : '<strong style="color:#ef4444;">✗ 不是高斯素数（可分解）</strong>'}`;
    };
    document.getElementById('ex12_scan').onclick = () => {
      const cv = document.getElementById('ex12_cv');
      const ctx = cv.getContext('2d');
      const W = cv.width, H = cv.height;
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      const N = 30, cx = W / 2, cy = H / 2, scale = 5;
      ctx.strokeStyle = '#e5e7eb';
      for (let i = -N; i <= N; i++) {
        ctx.beginPath();
        ctx.moveTo(cx + i * scale, 0); ctx.lineTo(cx + i * scale, H);
        ctx.moveTo(0, cy + i * scale); ctx.lineTo(W, cy + i * scale);
        ctx.stroke();
      }
      ctx.strokeStyle = '#1f2937'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(0, cy); ctx.lineTo(W, cy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx, 0); ctx.lineTo(cx, H); ctx.stroke();
      for (let a = -N; a <= N; a++) for (let b = -N; b <= N; b++) {
        if (a === 0 && b === 0) continue;
        if (isGaussianPrime(a, b)) {
          ctx.fillStyle = '#7c3aed';
          ctx.beginPath();
          ctx.arc(cx + a * scale, cy - b * scale, 2.5, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    };
  }

(h) => {
