(h) => {
    h.innerHTML = `<div class="row"><label>矩阵 N <input type="number" id="ex14_n" value="50" min="5" max="200"></label><label>样本数 <input type="number" id="ex14_m" value="100" min="10" max="500"></label><button class="primary" id="ex14_run">生成 + 画</button></div><div id="ex14_out" style="margin-top: 12px; padding: 12px; background: #f0fdf4; border-radius: 8px; font-family: 'Courier New', monospace;"></div><canvas id="ex14_cv" width="400" height="400" style="margin-top: 12px; max-width: 100%; border: 1px solid var(--line); border-radius: 6px;"></canvas>`;
    // 实随机矩阵特征值（用 QR 迭代替代——这里用简化：随机矩阵 + 显示经验分布）
    const randn = () => { const u = Math.random(), v = Math.random(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
    const qrEig = (A) => {
      // 简化：Hessenberg + QR（用不到此函数，仅画图）
      const n = A.length;
      const copy = A.map(r => r.slice());
      for (let iter = 0; iter < 200; iter++) {
        // QR 分解（Gram-Schmidt）
        const Q = Array.from({ length: n }, () => new Array(n).fill(0));
        const R = Array.from({ length: n }, () => new Array(n).fill(0));
        for (let j = 0; j < n; j++) {
          let v = copy.map(r => r[j]);
          for (let i = 0; i < j; i++) {
            let dot = 0; for (let k = 0; k < n; k++) dot += v[k] * Q[k][i];
            R[i][j] = dot;
            for (let k = 0; k < n; k++) v[k] -= dot * Q[k][i];
          }
          let norm = Math.sqrt(v.reduce((a, b) => a + b * b, 0));
          R[j][j] = norm;
          if (norm > 1e-12) for (let k = 0; k < n; k++) Q[k][j] = v[k] / norm;
        }
        // A = RQ
        for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
          copy[i][j] = 0;
          for (let k = 0; k < n; k++) copy[i][j] += R[i][k] * Q[k][j];
        }
      }
      // 特征值在对角线（实矩阵近似收敛到三角阵）
      return copy.map((r, i) => r[i]);
    };
    document.getElementById('ex14_run').onclick = () => {
      const N = +document.getElementById('ex14_n').value;
      const M = +document.getElementById('ex14_m').value;
      const cv = document.getElementById('ex14_cv');
      const ctx = cv.getContext('2d');
      const W = cv.width, H = cv.height;
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      // Girko 圆定律：实随机矩阵特征值
      const points = [];
      for (let s = 0; s < M; s++) {
        const A = Array.from({ length: N }, () => Array.from({ length: N }, () => randn() / Math.sqrt(N)));
        const eig = qrEig(A);
        for (const v of eig) {
          if (!isNaN(v) && isFinite(v) && Math.abs(v) < 3) points.push([v, (Math.random() - 0.5) * 0.05]);
        }
      }
      // 画圆盘边界
      const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 30;
      ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 2; ctx.setLineDash([5, 5]);
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
      ctx.setLineDash([]);
      // 画点
      for (const [x, y] of points) {
        const px = cx + x * R / 2.5;
        const py = cy + y * R / 2.5 - points[0] ? 0 : 0;
        ctx.fillStyle = 'rgba(124, 58, 237, 0.6)';
        ctx.fillRect(px, cy + y * R, 1.5, 1.5);
      }
      ctx.fillStyle = '#1f2937'; ctx.font = '13px sans-serif';
      ctx.fillText('Girko 圆：|λ| ≤ 2√N', 20, 20);
      document.getElementById('ex14_out').innerHTML = `生成 ${M} 个 N=${N} 随机矩阵<br>特征值数：${points.length}<br>应落入圆盘内（Girko 圆定律）`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>τ = x+yi <input type="number" id="ex15_x" value="0.3" min="-2" max="2" step="0.1"></label><label>y <input type="number" id="ex15_y" value="0.5" min="0.01" max="2" step="0.05"></label><button class="primary" id="ex15_run">q-展开</button><button class="ghost" id="ex15_lattice">画格点</button></div><div id="ex15_out" style="margin-top: 12px; padding: 12px; background: #faf5ff; border-radius: 8px; font-family: 'Courier New', monospace;"></div><svg id="ex15_svg" viewBox="0 0 400 400" style="margin-top: 12px; max-width: 100%; background: #fff; border: 1px solid var(--line); border-radius: 6px;"></svg>`;
