      const x = +document.getElementById('ex15_x').value;
      const y = +document.getElementById('ex15_y').value;
      // q = e^(2πiτ) = e^(-2πy) · e^(2πix)
      const qMag = Math.exp(-2 * Math.PI * y);
      let series = 'q-expansion (前 12 项)：<br>';
      // Δ(τ) = q · Π(1 - q^n)^24 简化为：q · exp(-24·Σ q^n/n)
