      let prodMag = 1;
      for (let n = 1; n <= 50; n++) prodMag *= Math.abs(1 - Math.pow(qMag, n));
      const deltaMag = qMag * Math.pow(prodMag, 24);
      series += `q = e^(2πi·${x.toFixed(2)}+${y.toFixed(2)}i)<br>`;
      series += `|q| = e^(-2πy) = <strong style="color:#7c3aed;">${qMag.toExponential(4)}</strong><br>`;
      series += `|Δ(τ)| = |q| · Π|1-q^n|^24 ≈ <strong style="color:#a855f7;">${deltaMag.toExponential(4)}</strong><br>`;
      series += `(Δ 模形式，权重 12，由拉马努金研究)`;
